const body = $input.first().json.body;

const required = ['book_title', 'author', 'pages_read', 'user_id'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing fields: ${missing.join(', ')}` } }];
}

const pagesRead = parseInt(body.pages_read);
if (isNaN(pagesRead) || pagesRead < 1) {
  return [{ json: { valid: false, error: 'pages_read must be a positive integer' } }];
}

return [{
  json: {
    valid: true,
    userId: body.user_id,
    bookTitle: body.book_title.trim(),
    author: body.author.trim(),
    pagesRead,
    currentPage: parseInt(body.current_page) || null,
    totalPages: parseInt(body.total_pages) || null,
    notes: (body.notes || '').trim().slice(0, 1000),
    rating: parseInt(body.rating) || null,
    finished: body.finished === true || body.finished === 'true',
    sessionDate: body.session_date || new Date().toISOString().split('T')[0]
  }
}];

const sessions = $input.all().map(s => s.json);
const current = $('Validate Input').first().json;

if (!sessions.length) {
  return [{ json: { stats: null, currentBook: current, isFirstSession: true } }];
}

// group by book
const byBook = {};
for (const s of sessions) {
  const key = `${s.book_title}|||${s.author}`;
  if (!byBook[key]) byBook[key] = [];
  byBook[key].push(s);
}

// books completed
const completedBooks = Object.values(byBook).filter(sessions =>
  sessions.some(s => s.finished === true || s.finished === 'TRUE')
).length;

// total pages all time
const totalPagesAllTime = sessions.reduce((sum, s) => sum + (parseInt(s.pages_read) || 0), 0);

// streak calculation
const sessionDates = [...new Set(sessions.map(s => s.session_date))].sort().reverse();
let streak = 0;
const today = new Date().toISOString().split('T')[0];
let checkDate = new Date(today);
for (const d of sessionDates) {
  const diff = (checkDate - new Date(d)) / 86400000;
  if (diff <= 1) { streak++; checkDate = new Date(d); }
  else break;
}

// current book progress
const currentBookSessions = sessions.filter(s =>
  s.book_title === current.bookTitle && s.author === current.author
);
const pagesInCurrentBook = currentBookSessions.reduce((sum, s) => sum + (parseInt(s.pages_read) || 0), 0) + current.pagesRead;

// avg pages per session (last 14 days)
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 14);
const recentSessions = sessions.filter(s => new Date(s.session_date) >= cutoff);
const avgPages = recentSessions.length
  ? Math.round(recentSessions.reduce((sum, s) => sum + (parseInt(s.pages_read) || 0), 0) / recentSessions.length)
  : current.pagesRead;

// estimate days to finish
let daysToFinish = null;
if (current.totalPages && current.currentPage) {
  const remaining = current.totalPages - current.currentPage;
  daysToFinish = avgPages > 0 ? Math.ceil(remaining / avgPages) : null;
}

// all notes from current book
const currentBookNotes = currentBookSessions
  .filter(s => s.notes && s.notes.trim())
  .map(s => s.notes)
  .join(' | ');

return [{
  json: {
    stats: {
      totalSessions: sessions.length,
      completedBooks,
      totalPagesAllTime,
      streak,
      avgPagesPerSession: avgPages,
      daysToFinish,
      pagesInCurrentBook
    },
    currentBook: current,
    currentBookNotes,
    isFirstSession: false
  }
}];

