const statsData = $('Compute Stats').first().json;
const insightNode = $input.first();
const insight = insightNode?.json?.text || insightNode?.json?.content?.[0]?.text || null;

const s = statsData.stats;
const book = statsData.currentBook;

const progressPct = book.totalPages && book.currentPage
  ? Math.round((book.currentPage / book.totalPages) * 100)
  : null;

const progressBar = progressPct !== null
  ? `[${'█'.repeat(Math.round(progressPct/5))}${'░'.repeat(20 - Math.round(progressPct/5))}] ${progressPct}%`
  : null;

const finishMsg = s?.daysToFinish
  ? `At your current pace (~${s.avgPagesPerSession} pages/session), you'll finish in ~${s.daysToFinish} days.`
  : null;

const streakMsg = s?.streak > 1 ? `🔥 ${s.streak}-day reading streak` : null;

const response = {
  status: 'logged',
  session: {
    book: book.bookTitle,
    author: book.author,
    pagesRead: book.pagesRead,
    date: book.sessionDate
  },
  stats: s ? {
    streak: s.streak,
    totalPagesAllTime: s.totalPagesAllTime,
    booksCompleted: s.completedBooks,
    avgPagesPerSession: s.avgPagesPerSession,
    daysToFinish: s.daysToFinish
  } : null,
  progress: progressBar,
  finishEstimate: finishMsg,
  streakAlert: streakMsg,
  insight: insight || null
};

return [{ json: response }];
